//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::net::pton_v6`; the
//! native twin is `benches/native/Bench/NetPtonV6.lean`.
//! 16 texts, valid and not; Lean's Array.get! retains and releases the string it reads, the Rust
//! side borrows it
//! NOT COMPARABLE: Lean's API allocates the `some` and the address's array of boxed numbers; the
//! crate returns plain data, and a translator's cost depends on its representation of the result

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::net;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<String>, n: u64) -> u64 {
    let ss = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match net::pton_v6(get_str(ss, x >> 60)) {
                Some(w) => w
                    .iter()
                    .fold(0u64, |a, &s| a.rotate_left(16) ^ u64::from(s)),
                None => 1 << 40,
            },
        );
    }
    acc
}

fn main() {
    run(|| ipv6_texts(), kernel)
}
